transformStepData.code:
// 步骤间数据转换逻辑
if (stepId === 'select-baseline') {
  return {
    ...data,
    baselineDatasourceId: data.datasourceId,
    baselineTableName: data.name,
    baselineTableType: data.type
  };
}
if (stepId === 'upload-file') {
  return {
    ...data,
    fileId: data.id,
    fileName: data.name,
    fileType: data.type
  };
}
if (stepId === 'field-mapping') {
  return {
    ...data,
    fieldMapping: {
      transactionDate: data.transactionDateField,
      amount: data.amountField,
      counterparty: data.counterpartyField,
      summary: data.summaryField
    }
  };
}
if (stepId === 'match-config') {
  return {
    ...data,
    config: {
      amountTolerance: data.amountTolerance,
      dateTolerance: data.dateTolerance,
      minMatchScore: data.minMatchScore
    }
  };
}
return data;

prepareStepOutput.code:
// 准备步骤输出数据
if (stepId === 'execute') {
  return {
    ...data,
    executionId: data.id,
    status: data.status,
    progress: data.progress,
    logs: data.logs
  };
}
if (stepId === 'result') {
  return {
    ...data,
    taskId: data.taskId,
    summary: data.summary,
    matches: data.matches,
    differences: data.differences,
    unmatched: data.unmatched
  };
}
return data;

validateStepData.code:
// 验证步骤数据
const errors = [];
if (stepId === 'select-baseline') {
  if (!data.datasourceId) errors.push('请选择对账基准');
}
if (stepId === 'upload-file') {
  if (!data.id) errors.push('请上传对账文件');
}
if (stepId === 'field-mapping') {
  if (!data.transactionDateField) errors.push('请选择交易日期字段');
  if (!data.amountField) errors.push('请选择金额字段');
}
if (stepId === 'match-config') {
  if (data.amountTolerance < 0) errors.push('金额容差不能为负数');
  if (data.dateTolerance < 0) errors.push('日期容差不能为负数');
  if (data.minMatchScore < 0 || data.minMatchScore > 100) errors.push('最低匹配得分必须在0-100之间');
}
return { valid: errors.length === 0, errors };
